{"sql": "WITH batting_clean AS (
  SELECT player_id, TRY_CAST(g AS INTEGER) as g, TRY_CAST(r AS INTEGER) as r, TRY_CAST(h AS INTEGER) as h, TRY_CAST(hr AS INTEGER) as hr
  FROM batting
)
SELECT player_id, SUM(g) as total_g, SUM(r) as total_r, SUM(h) as total_h, SUM(hr) as total_hr FROM batting_clean GROUP BY player_id ORDER BY total_g DESC LIMIT 10"}
